// Room discovery and a reliable HTTP relay remain available when direct WebRTC is blocked.
export class RoomConnection {
 constructor(callbacks={}){this.callbacks=callbacks;this.peers=new Map();this.signals=[];this.seenSignals=new Map();this.roster=[];this.remoteInputs=new Map();this.memberGenerations=new Map();this.active=false;this.isHost=false;this.latestSnapshot=null;this.latestInput=null;this.lastSnapshotSeq=0;this.lastSuccess=0;this.failures=0;this.inputSeq=0;this.roundEpoch='';this.press={dodge:0,catch:0,jump:0,crouch:0};this.previous={};}
 async request(action,body={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),6000);try{const response=await fetch(`/api/rooms/${action}`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:this.code,token:this.token,...body}),signal:controller.signal});let data;try{data=await response.json();}catch{throw new Error('This host needs the Potatoman online room server.');}if(!response.ok)throw Object.assign(new Error(data.error||'Connection failed.'),{status:response.status});return data;}finally{clearTimeout(timer);}}
 async connect(action,name,code){const data=await this.request(action,{name,code});Object.assign(this,data);this.isHost=this.slot===0;this.active=true;this.lastSuccess=Date.now();await this.poll();if(!this.active)throw Error('The room closed while you were joining. Create or join another room.');return data;}
 async poll(){if(!this.active)return;const outgoing=this.signals.splice(0),sentStart=this.startRequested;try{const direct=this.isHost?this.roster.filter(m=>m.slot!==0).every(m=>this.direct(m.slot)):this.direct(0);const data=await this.request('exchange',{signals:outgoing,start:sentStart,input:this.isHost?undefined:this.latestInput,snapshot:this.isHost?this.latestSnapshot:undefined});if(!this.active)return;if(sentStart)this.startRequested=false;this.lastBackup=Date.now();this.lastSuccess=Date.now();this.failures=0;this.roster=data.roster;this.status=data.status;
  for(const member of this.roster)if(this.isHost&&member.slot!==0){if(this.memberGenerations.get(member.slot)!==member.generation){this.peers.get(member.slot)?.pc.close();this.peers.delete(member.slot);this.remoteInputs.delete(member.slot);this.seenSignals.clear();this.memberGenerations.set(member.slot,member.generation);}if(member.input)this.receiveInput(member.slot,member.input);this.ensurePeer(member.slot);}
  for(const [slot,p]of this.peers)if(!this.roster.some(m=>m.slot===slot)){p.pc.close();this.peers.delete(slot);this.remoteInputs.delete(slot);}
  for(const s of data.signals){const key=s.from+':'+s.description.sdp;if(!this.seenSignals.has(key)){this.seenSignals.set(key,true);this.acceptSignal(s).catch(()=>{});}}
  if(!this.isHost&&data.snapshot)this.receiveSnapshot(data.snapshot);
  this.callbacks.roster?.(this.roster,data.status);this.callbacks.connection?.(direct?'Direct connection':'Relay connection');
 }catch(e){if(!this.active)return;this.signals.unshift(...outgoing);this.failures++;this.callbacks.connection?.('Reconnecting…');if([403,404,410].includes(e.status)||Date.now()-this.lastSuccess>15000){this.callbacks.closed?.(e.message);await this.close(false);return;}}
 if(this.active)this.timer=setTimeout(()=>this.poll(),this.status==='playing'&&(this.isHost?!this.roster.filter(m=>m.slot!==0).every(m=>this.direct(m.slot)):!this.direct(0))?100:900);
 }
 direct(slot){const p=this.peers.get(slot);return p?.channel?.readyState==='open'&&performance.now()-(p.lastPacket??0)<1500;}
 channel(slot,channel){const peer=this.peers.get(slot);peer.channel=channel;channel.onopen=()=>{peer.lastPacket=performance.now();};channel.onmessage=e=>{peer.lastPacket=performance.now();try{const packet=JSON.parse(e.data);if(this.isHost&&packet.type==='input')this.receiveInput(slot,packet.data);if(!this.isHost&&slot===0&&packet.type==='snapshot')this.receiveSnapshot(packet.data);}catch{}};}
 ensurePeer(slot){if(this.peers.has(slot)||typeof RTCPeerConnection==='undefined')return;const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});this.peers.set(slot,{pc});pc.ondatachannel=e=>this.channel(slot,e.channel);if(this.isHost){this.channel(slot,pc.createDataChannel('potatoman',{ordered:false,maxRetransmits:0}));this.makeDescription(slot,'offer').catch(()=>{});}return pc;}
 async makeDescription(slot,type){const pc=this.peers.get(slot).pc;await pc.setLocalDescription(await(type==='offer'?pc.createOffer():pc.createAnswer()));if(pc.iceGatheringState!=='complete')await new Promise(resolve=>{const finish=()=>{clearTimeout(timer);pc.removeEventListener('icegatheringstatechange',changed);resolve();};const changed=()=>{if(pc.iceGatheringState==='complete')finish();};const timer=setTimeout(finish,2500);pc.addEventListener('icegatheringstatechange',changed);});this.signals.push({to:slot,description:{type:pc.localDescription.type,sdp:pc.localDescription.sdp}});}
 async acceptSignal(s){this.ensurePeer(s.from);const peer=this.peers.get(s.from);if(!peer)return;await peer.pc.setRemoteDescription(s.description);if(s.description.type==='offer')await this.makeDescription(s.from,'answer');}
 send(slot,type,data){const channel=this.peers.get(slot)?.channel;if(channel?.readyState==='open'&&channel.bufferedAmount<100000){try{channel.send(JSON.stringify({type,data}));}catch{}}}
 publish(snapshot){this.latestSnapshot=snapshot;for(const member of this.roster)if(member.slot!==0)this.send(member.slot,'snapshot',snapshot);}
 receiveSnapshot(snapshot){if(snapshot?.version&&snapshot.version!==10){this.callbacks.closed?.('This room uses a different game update. Everyone should reload the game, then create a new room.');this.close(false);return;}if(!snapshot||!Number.isInteger(snapshot.seq)||snapshot.seq<=this.lastSnapshotSeq)return;this.lastSnapshotSeq=snapshot.seq;this.callbacks.snapshot?.(snapshot);}
 receiveInput(slot,input){if(!input||!Number.isFinite(input.seq)||input.seq<=(this.remoteInputs.get(slot)?.data.seq??0))return;this.remoteInputs.set(slot,{data:input,received:performance.now()});}
 observeInput(input,epoch){if(epoch!==this.roundEpoch){this.roundEpoch=epoch;this.press={dodge:0,catch:0,jump:0,crouch:0};this.previous={};}for(const key of['dodge','catch','jump','crouch']){if(input[key]&&!this.previous[key])this.press[key]++;this.previous[key]=input[key];}}
 input(input,p,epoch){this.observeInput(input,epoch);this.latestInput={seq:++this.inputSeq,epoch,x:input.x,z:input.z,yaw:p.yaw,pitch:p.pitch,fire:input.fire,crouch:input.crouch,crouchSerial:this.press.crouch,zoom:p.cameraDistance??4.6,dodge:this.press.dodge,catch:this.press.catch,jump:this.press.jump};this.send(0,'input',this.latestInput);return this.latestInput;}
 async close(notify=true){this.active=false;clearTimeout(this.timer);for(const p of this.peers.values())p.pc.close();this.peers.clear();if(notify&&this.token)try{await this.request('leave');}catch{}}
}
